import 'dart:convert';

import 'package:patrol_recorder/model.dart';
import 'package:yaml/yaml.dart';

import 'generator.dart';
import 'authored_step.dart';
import 'file_export.dart';

part 'journey_schema.dart';

const journeySchemaVersion = 5;
const journeyHeader =
    '# Generated by Patrol Recorder. Re-record to replace this file.\n';

const _selectorNames = <SelectorKind, String>{
  SelectorKind.key: 'key',
  SelectorKind.semanticsIdentifier: 'semantics_id',
  SelectorKind.semanticsLabel: 'semantics_label',
  SelectorKind.fieldLabel: 'field_label',
  SelectorKind.text: 'text',
  SelectorKind.richText: 'rich_text',
  SelectorKind.widgetType: 'widget_type',
};

Map<String, Object?> _targetYaml(RecorderTarget target) => {
  _selectorNames[target.selector!.kind]!: target.selector!.value,
  if (target.scope != null)
    'within': {_selectorNames[target.scope!.kind]!: target.scope!.value},
};

RecorderSelector _selectorFromYaml(Map<String, dynamic> map) {
  if (map.length != 1) {
    throw const FormatException('A target needs exactly one selector.');
  }
  final entry = map.entries.single;
  final kinds = _selectorNames.entries.where((e) => e.value == entry.key);
  if (kinds.length != 1 || entry.value is! String) {
    throw const FormatException(
      'Unknown selector. Coordinate/index selectors are not supported.',
    );
  }
  return RecorderSelector(kinds.single.key, entry.value as String);
}

Map<String, dynamic> _map(Object? value, String name) {
  if (value is! Map || value.keys.any((key) => key is! String)) {
    throw FormatException('$name must be a mapping with string keys.');
  }
  return {for (final entry in value.entries) entry.key as String: entry.value};
}

void _keys(Map<String, dynamic> map, Set<String> allowed, String name) {
  if (map.keys.any((key) => !allowed.contains(key))) {
    throw FormatException('Unknown field in $name.');
  }
}

String _string(Object? value, String name) {
  if (value is! String || value.isEmpty || value.length > 1000) {
    throw FormatException(
      '$name must be a nonempty string of at most 1000 characters.',
    );
  }
  return value;
}

class JourneyCapture {
  JourneyCapture({
    required this.name,
    required this.path,
    required this.width,
    required this.height,
    required this.redactedRegions,
    this.afterStep,
  }) {
    requireIdentifier(name, 'Screenshot name');
    validateRelativePath(path);
    if (!path.endsWith('.png') ||
        width <= 0 ||
        height <= 0 ||
        width * height > 8000000 ||
        redactedRegions < 0) {
      throw const FormatException('Invalid screenshot metadata.');
    }
    if (afterStep != null) requireIdentifier(afterStep!, 'Screenshot step ID');
  }
  final String name;
  final String path;
  final String? afterStep;
  final int width;
  final int height;
  final int redactedRegions;

  Map<String, Object?> toMap() => {
    'name': name,
    'path': path,
    'after_step': afterStep,
    'width': width,
    'height': height,
    'redacted_regions': redactedRegions,
    'extent': 'visible_viewport',
  };

  factory JourneyCapture.fromMap(Object? value, {bool legacy = false}) {
    final map = _map(value, 'screenshot');
    _keys(map, {
      if (legacy) 'id' else 'name',
      'path',
      'after_step',
      'width',
      'height',
      'redacted_regions',
      'extent',
    }, 'screenshot');
    if (map['width'] is! int ||
        map['height'] is! int ||
        map['redacted_regions'] is! int ||
        map['extent'] != 'visible_viewport' ||
        map['after_step'] != null && map['after_step'] is! String) {
      throw const FormatException('Invalid screenshot fields.');
    }
    return JourneyCapture(
      name: _string(map[legacy ? 'id' : 'name'], 'Screenshot name'),
      path: _string(map['path'], 'Screenshot path'),
      width: map['width'] as int,
      height: map['height'] as int,
      redactedRegions: map['redacted_regions'] as int,
      afterStep: map['after_step'] as String?,
    );
  }
}

class RecordedJourney {
  RecordedJourney({
    required this.id,
    required this.name,
    required this.caseId,
    required this.profile,
    required this.state,
    this.legacyApp,
    required List<RecordedStep> steps,
    Set<String> excluded = const {},
    List<JourneyCapture> screenshots = const [],
    this.recordingError,
    this.acknowledgedIncomplete = false,
    Map<String, JourneyAsset> assets = const {},
    Map<String, JourneyInput> inputs = const {},
    Map<String, Map<String, Object?>> profiles = const {},
    Map<String, List<RecordedStep>> groups = const {},
    Map<String, List<RecordedStep>> setup = const {},
    List<JourneyCase> cases = const [],
    Map<String, RecorderTarget> selectorOverrides = const {},
  }) : steps = List.unmodifiable(steps),
       excluded = Set.unmodifiable(excluded),
       screenshots = List.unmodifiable(screenshots),
       assets = Map.unmodifiable(assets),
       inputs = Map.unmodifiable(inputs),
       profiles = Map.unmodifiable({
         for (final entry in profiles.entries)
           entry.key: freezeJourneyData(entry.value),
       }),
       groups = Map.unmodifiable({
         for (final entry in groups.entries)
           entry.key: List<RecordedStep>.unmodifiable(entry.value),
       }),
       setup = Map.unmodifiable({
         for (final entry in setup.entries)
           entry.key: List<RecordedStep>.unmodifiable(entry.value),
       }),
       cases = List.unmodifiable(cases),
       selectorOverrides = Map.unmodifiable(selectorOverrides) {
    ExportConfig(
      journeyId: id,
      caseName: name,
      caseId: caseId,
      profile: profile,
    );
    if (state != 'recording' && state != 'stopped') {
      throw const FormatException(
        'Journey state must be recording or stopped.',
      );
    }
    final ids = steps.map((s) => s.id).toSet();
    if (steps.length > 500 ||
        ids.length != steps.length ||
        excluded.any((id) => !ids.contains(id))) {
      throw const FormatException(
        'Invalid, duplicate, or excessive recorded steps.',
      );
    }
    if (screenshots.length > 10 ||
        screenshots.map((s) => s.name).toSet().length != screenshots.length ||
        screenshots.map((s) => s.path).toSet().length != screenshots.length ||
        screenshots.any(
          (s) => s.afterStep != null && !ids.contains(s.afterStep),
        )) {
      throw const FormatException('Invalid screenshot associations.');
    }
    _validateJourney(this);
  }

  final String id, name, caseId, profile, state;
  final RecorderAppConfig? legacyApp;
  final List<RecordedStep> steps;
  final Set<String> excluded;
  final List<JourneyCapture> screenshots;
  final String? recordingError;
  final bool acknowledgedIncomplete;
  final Map<String, JourneyAsset> assets;
  final Map<String, JourneyInput> inputs;
  final Map<String, Map<String, Object?>> profiles;
  final Map<String, List<RecordedStep>> groups, setup;
  final List<JourneyCase> cases;
  final Map<String, RecorderTarget> selectorOverrides;

  String toYaml() => journeyHeader + _yaml(_journeyMap(this));

  factory RecordedJourney.fromYaml(String source) {
    if (source.length > 1024 * 1024) {
      throw const FormatException('Journey YAML exceeds 1 MiB.');
    }
    final Map<String, dynamic> map;
    try {
      map = _map(loadYaml(source), 'journey file');
    } on YamlException catch (error) {
      throw FormatException('Invalid journey YAML: ${error.message}');
    }
    if (map['schema_version'] == 5 && map['schema_version'] is int) {
      return _parseV5(map);
    }
    final legacy = map['schema_version'] == 1;
    _keys(map, {
      'schema_version',
      'journey',
      if (legacy) 'session_id',
      'state',
      if (legacy) 'app',
      'steps',
      'screenshots',
      'recording_error',
      'acknowledged_incomplete',
    }, 'journey file');
    if (map['schema_version'] is! int ||
        (map['schema_version'] != journeySchemaVersion &&
            map['schema_version'] != 4 &&
            map['schema_version'] != 3 &&
            map['schema_version'] != 2 &&
            !legacy) ||
        map['steps'] is! List ||
        map['screenshots'] is! List ||
        map['acknowledged_incomplete'] is! bool ||
        map['recording_error'] != null && map['recording_error'] is! String) {
      throw const FormatException(
        'Invalid or incompatible journey YAML schema.',
      );
    }
    final identity = _map(map['journey'], 'journey');
    _keys(identity, {'id', 'name', 'case_id', 'profile'}, 'journey');
    RecorderAppConfig? legacyApp;
    if (legacy) {
      requireIdentifier(_string(map['session_id'], 'Session ID'), 'Session ID');
      final appMap = _map(map['app'], 'app');
      _keys(appMap, {'import', 'builder'}, 'app');
      legacyApp = RecorderAppConfig(
        appImport: _string(appMap['import'], 'App import'),
        appBuilder: _string(appMap['builder'], 'App builder'),
      );
    }
    final steps = <RecordedStep>[];
    final excluded = <String>{};
    for (final raw in map['steps'] as List) {
      final step = _map(raw, 'step');
      if ((map['schema_version'] as int) < 4 && step['action'] == 'expect') {
        throw const FormatException('Expect steps require schema 4.');
      }
      if ((map['schema_version'] as int) < 3 &&
          [
            'tapText',
            'longPress',
            'scrollUntilVisible',
          ].contains(step['action'])) {
        throw const FormatException(
          'This action requires schema 3. Re-record the journey with the current recorder.',
        );
      }
      _keys(step, {
        'id',
        'action',
        'target',
        'review',
        'source',
        'include',
        'input',
        'secret',
        'text',
        'scroll_view',
        'direction',
        'expectation',
      }, 'step');
      if (step['include'] is! bool) {
        throw const FormatException('A step needs an include flag.');
      }
      String? input;
      if (step['action'] == 'enterText') {
        final reference = step['input'];
        if (reference is! String) {
          throw const FormatException('Input must be a {{name}} reference.');
        }
        final match = RegExp(r'^\{\{([a-z][a-z0-9_]{0,63})\}\}$')
            .firstMatch(reference);
        if (match == null || step['secret'] is! bool) {
          throw const FormatException(
            'Text actions require a {{name}} reference and a secret flag, never literal values.',
          );
        }
        input = match.group(1)!;
      } else if (step.containsKey('input') || step.containsKey('secret')) {
        throw const FormatException(
          'Only text actions can contain an input reference.',
        );
      }
      final RecorderTarget target;
      if (step.containsKey('review')) {
        if (step.containsKey('target')) {
          throw const FormatException(
            'A review step cannot also claim a resolved target.',
          );
        }
        target = RecorderTarget(
          issue: _string(step['review'], 'Review reason'),
        );
      } else {
        final selector = _map(step['target'], 'target');
        final within = selector.remove('within');
        target = RecorderTarget(
          selector: _selectorFromYaml(selector),
          scope: within == null
              ? null
              : _selectorFromYaml(_map(within, 'within')),
        );
      }
      final recorded = RecordedStep.fromJson({
        'id': step['id'],
        'action': step['action'],
        'target': target.toJson(),
        'source': step['source'],
        'input': input,
        'secret': step['secret'] ?? false,
        if (step.containsKey('text')) 'text': step['text'],
        if (step.containsKey('expectation'))
          'expectation': _map(
            step['expectation'],
            '${step['id']}: expectation',
          ),
        if (step.containsKey('direction')) 'scrollDirection': step['direction'],
        if (step.containsKey('scroll_view'))
          'scrollView': _resolvedTarget(
            step['scroll_view'],
            'scroll_view',
          ).toJson(),
      });
      steps.add(recorded);
      if (step['include'] == false) excluded.add(recorded.id);
    }
    return RecordedJourney(
      id: _string(identity['id'], 'Journey ID'),
      name: _string(identity['name'], 'Journey name'),
      caseId: _string(identity['case_id'], 'Case ID'),
      profile: _string(identity['profile'], 'Profile'),
      state: _string(map['state'], 'State'),
      legacyApp: legacyApp,
      steps: steps,
      excluded: excluded,
      screenshots: (map['screenshots'] as List)
          .map((s) => JourneyCapture.fromMap(s, legacy: legacy))
          .toList(),
      recordingError: map['recording_error'] as String?,
      acknowledgedIncomplete: map['acknowledged_incomplete'] as bool,
    );
  }

  static RecorderTarget _resolvedTarget(Object? value, String name) {
    final selector = _map(value, name);
    final within = selector.remove('within');
    return RecorderTarget(
      selector: _selectorFromYaml(selector),
      scope: within == null
          ? null
          : _selectorFromYaml(_map(within, '$name.within')),
    );
  }

  List<JourneyCase> get effectiveCases => cases.isNotEmpty
      ? cases
      : [
          JourneyCase(
            id: caseId,
            name: name,
            profile: profile,
            steps: steps,
            excluded: excluded,
            selectorOverrides: selectorOverrides,
          ),
        ];

  Future<ResolvedJourneyAssets> resolveAssets(
    WorkspaceFiles workspace,
    Uri projectRoot,
    String recordingsDirectory,
  ) async {
    validateRelativePath(recordingsDirectory);
    if (projectRoot.scheme != 'file' || !projectRoot.path.endsWith('/')) {
      throw const FormatException('Assets require an authorized project root.');
    }
    final values = <String, Object>{};
    final sources = <Uri, String>{};
    var total = 0;
    for (final entry in assets.entries) {
      final asset = entry.value;
      final uri = projectRoot.resolve('$recordingsDirectory/${asset.path}');
      final source = await workspace.read(uri);
      if (source == null) {
        throw FormatException(
          'Journey $id: missing asset ${entry.key} at $recordingsDirectory/${asset.path}.',
        );
      }
      total += utf8.encode(source).length;
      if (total > 10 * 1024 * 1024) {
        throw FormatException(
          'Journey $id: assets exceed the 10 MiB aggregate limit.',
        );
      }
      try {
        values[entry.key] = asset.decode(source);
      } on FormatException catch (error) {
        throw FormatException(
          'Journey $id/asset ${entry.key}: ${error.message}',
        );
      }
      sources[uri] = source;
    }
    return ResolvedJourneyAssets(
      Map.unmodifiable(values),
      Map.unmodifiable(sources),
    );
  }

  List<RecordedStep> expandedSteps(JourneyCase selected) =>
      _expandCase(this, selected);

  List<Map<String, Object?>> inspectSelectors({String? selectedCase}) {
    if (selectedCase != null &&
        !effectiveCases.any((item) => item.id == selectedCase)) {
      throw FormatException('Journey $id: unknown case $selectedCase.');
    }
    return [
      for (final item in effectiveCases.where(
        (item) => selectedCase == null || item.id == selectedCase,
      ))
        for (final step in expandedSteps(item))
          if (step is! AssetStep)
            {
              'case_id': item.id,
              'id': step.id,
              'target': step.target.toJson(),
              'overridden': item.selectorOverrides.containsKey(step.id),
            },
    ];
  }

  GeneratedJourney generate(
    ExportConfig defaults, {
    RecorderAppConfig? app,
    Map<String, Object> assetValues = const {},
    String? selectedCase,
  }) {
    if (effectiveCases.length > 1 && selectedCase == null) {
      throw StateError(
        'Journey $id has multiple cases. Use generateCases or select a case.',
      );
    }
    return generateCases(
      defaults,
      app: app,
      assetValues: assetValues,
      selectedCase: selectedCase,
    ).single;
  }

  List<GeneratedJourney> generateCases(
    ExportConfig defaults, {
    RecorderAppConfig? app,
    Map<String, Object> assetValues = const {},
    String? selectedCase,
  }) {
    if (state != 'stopped') {
      throw StateError('Stop recording $id before generating code.');
    }
    if (recordingError != null && !acknowledgedIncomplete) {
      throw StateError(
        'Journey $id is incomplete. Review it in DevTools or re-record it.',
      );
    }
    final selected = effectiveCases
        .where((item) => selectedCase == null || item.id == selectedCase)
        .toList();
    if (selected.isEmpty) {
      throw FormatException('Journey $id: unknown case $selectedCase.');
    }
    return [
      for (final item in selected)
        _generateCase(item, defaults, app, assetValues),
    ];
  }

  GeneratedJourney _generateCase(
    JourneyCase item,
    ExportConfig defaults,
    RecorderAppConfig? app,
    Map<String, Object> assetValues,
  ) {
    final included = expandedSteps(item);
    final supplied = {...?profiles[item.profile], ...item.data};
    final requirements = requiredInputs(included);
    return generateJourney(
      steps: included,
      app:
          app ??
          legacyApp ??
          (throw StateError('Resolve the app entrypoint before generation.')),
      config: ExportConfig(
        outputDirectory: cases.isEmpty
            ? defaults.outputDirectory
            : '${defaults.outputDirectory}/$id/cases',
        recordingsDirectory: defaults.recordingsDirectory,
        screenshotsDirectory: defaults.screenshotsDirectory,
        waitTimeoutMs: defaults.waitTimeoutMs,
        maxScrolls: defaults.maxScrolls,
        journeyId: cases.isEmpty ? id : item.id,
        caseId: item.id,
        caseName: item.name,
        profile: item.profile,
      ),
      deferredInputs: {
        for (final requirement in requirements)
          if (!supplied.containsKey(requirement.name) && !requirement.secret)
            requirement.name,
        for (final entry in inputs.entries)
          if (!supplied.containsKey(entry.key) && !entry.value.secret)
            entry.key,
      },
      typedInputs: inputs,
      typedValues: supplied,
      typedProfiles: profiles,
      assetValues: assetValues,
      assetFormats: {
        for (final entry in assets.entries) entry.key: entry.value.format,
      },
    );
  }
}

class ResolvedJourneyAssets {
  const ResolvedJourneyAssets(this.values, this.sources);
  final Map<String, Object> values;
  final Map<Uri, String> sources;
}

String _yaml(Object? value, [int depth = 0]) {
  final indent = '  ' * depth;
  if (value is Map) {
    if (value.isEmpty) return '{}\n';
    return value.entries.map((entry) {
      final v = entry.value;
      final key = entry.key as String;
      final safeKey =
          RegExp(r'^[a-zA-Z_][a-zA-Z0-9_]*$').hasMatch(key) &&
          !{
            'true',
            'false',
            'null',
            'yes',
            'no',
            'on',
            'off',
          }.contains(key.toLowerCase());
      final encodedKey = safeKey ? key : jsonEncode(key);
      final nested = v is Map && v.isNotEmpty || v is List && v.isNotEmpty;
      return '$indent$encodedKey:${nested ? '\n${_yaml(v, depth + 1)}' : ' ${jsonEncode(v)}\n'}';
    }).join();
  }
  if (value is List) {
    if (value.isEmpty) return '[]\n';
    return value.map((v) => '$indent-\n${_yaml(v, depth + 1)}').join();
  }
  return '$indent${jsonEncode(value)}\n';
}
